result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/mapreduce.test.js", "content": "'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { Worker } = require('node:worker_threads');
const { performance } = require('node:perf_hooks');

const FILE = path.join(__dirname, 'events.jsonl');
const WORKER_FILE = path.join(__dirname, 'worker.js');

const LINES = 300000;
const USERS = 500;
const SEED = 0xc0ffee;
const NUM_WORKERS = 4;
const CHUNK_BYTES = 1 << 20;

// ---------------------------------------------------------------- dataset ---

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function ensureDataset() {
  if (fs.existsSync(FILE) && fs.statSync(FILE).size > 0) return;
  const rng = mulberry32(SEED);
  const parts = [];
  let buf = '';
  for (let i = 0; i < LINES; i++) {
    const user = Math.floor(rng() * USERS) + 1;
    const ms = Math.floor(rng() * 1000) + 1;
    buf += `{"user":"u${user}","ms":${ms}}\n`;
    if (buf.length >= CHUNK_BYTES) {
      parts.push(buf);
      buf = '';
    }
  }
  parts.push(buf);
  fs.writeFileSync(FILE, parts.join(''));
}

// ------------------------------------------------------------- segmenting ---

// Position of the first '\n' at or after `from` (returns fileSize if none).
function findNewlineAtOrAfter(fd, from, fileSize) {
  const chunk = Buffer.allocUnsafe(4096);
  let pos = from;
  while (pos < fileSize) {
    const want = Math.min(chunk.length, fileSize - pos);
    const n = fs.readSync(fd, chunk, 0, want, pos);
    if (n === 0) break;
    const idx = chunk.indexOf(10, 0, n);
    if (idx !== -1) return pos + idx;
    pos += n;
  }
  return fileSize;
}

function splitSegments(fileSize, n) {
  const fd = fs.openSync(FILE, 'r');
  try {
    const segments = [];
    let start = 0;
    for (let k = 1; k <= n; k++) {
      if (k === n) {
        segments.push({ start, end: fileSize });
        break;
      }
      const approx = Math.round((fileSize * k) / n);
      const nlPos = findNewlineAtOrAfter(fd, approx, fileSize);
      const end = Math.min(nlPos + 1, fileSize); // include the '\n'
      segments.push({ start, end });
      start = end;
    }
    // sanity: contiguous, ordered, full coverage
    assert.ok(segments[0].start === 0);
    assert.ok(segments[segments.length - 1].end === fileSize);
    for (let i = 1; i < segments.length; i++) {
      assert.ok(segments[i].start === segments[i - 1].end);
    }
    return segments;
  } finally {
    fs.closeSync(fd);
  }
}

// ------------------------------------------------------------- map-reduce ---

function runWorker(segment) {
  return new Promise((resolve, reject) => {
    const w = new Worker(WORKER_FILE, {
      workerData: { file: FILE, start: segment.start, end: segment.end },
    });
    w.on('message', resolve);
    w.on('error', reject);
    w.on('exit', (code) => {
      if (code !== 0) reject(new Error(`worker exited with ${code}`));
    });
  });
}

async function mapReduce(nWorkers) {
  const { size } = fs.statSync(FILE);
  const segments = splitSegments(size, nWorkers);
  const partials = await Promise.all(segments.map(runWorker));

  // merge on the main thread
  const merged = new Map();
  for (const partial of partials) {
    for (const [user, rec] of Object.entries(partial)) {
      let a = merged.get(user);
      if (a === undefined) merged.set(user, (a = { count: 0, total_ms: 0, max_ms: 0 }));
      a.count += rec.count;
      a.total_ms += rec.total_ms;
      if (rec.max_ms > a.max_ms) a.max_ms = rec.max_ms;
    }
  }
  return merged;
}

// ------------------------------------------------------------------ oracle ---

function singleThreadPass() {
  const fd = fs.openSync(FILE, 'r');
  const buf = Buffer.allocUnsafe(CHUNK_BYTES);
  const oracle = new Map();
  let carry = '';
  try {
    let filePos = 0;
    for (;;) {
      const n = fs.readSync(fd, buf, 0, buf.length, filePos);
      if (n === 0) break;
      filePos += n;
      const text = carry + buf.toString('utf8', 0, n);
      let start = 0;
      for (;;) {
        const nl = text.indexOf('\n', start);
        if (nl === -1) break;
        const line = text.slice(start, nl);
        start = nl + 1;
        if (line.length > 0) {
          const rec = JSON.parse(line);
          let a = oracle.get(rec.user);
          if (a === undefined) oracle.set(rec.user, (a = { count: 0, total_ms: 0, max_ms: 0 }));
          a.count += 1;
          a.total_ms += rec.ms;
          if (rec.ms > a.max_ms) a.max_ms = rec.ms;
        }
      }
      carry = text.slice(start);
    }
    if (carry.length > 0) {
      const rec = JSON.parse(carry);
      let a = oracle.get(rec.user);
      if (a === undefined) oracle.set(rec.user, (a = { count: 0, total_ms: 0, max_ms: 0 }));
      a.count += 1;
      a.total_ms += rec.ms;
      if (rec.ms > a.max_ms) a.max_ms = rec.ms;
    }
  } finally {
    fs.closeSync(fd);
  }
  return oracle;
}

// ------------------------------------------------------------------- test ---

test('map-reduce over worker_threads matches single-threaded oracle', async () => {
  ensureDataset();

  const mrStart = performance.now();
  const merged = await mapReduce(NUM_WORKERS);
  const mrMs = performance.now() - mrStart;

  const oracleStart = performance.now();
  const oracle = singleThreadPass();
  const oracleMs = performance.now() - oracleStart;

  console.log(`map-reduce (${NUM_WORKERS} workers): ${mrMs.toFixed(1)} ms`);
  console.log(`oracle (single thread):     ${oracleMs.toFixed(1)} ms`);

  assert.strictEqual(merged.size, USERS, 'merged covers exactly 500 users');
  assert.strictEqual(oracle.size, USERS, 'oracle covers exactly 500 users');

  for (let u = 1; u <= USERS; u++) {
    const key = `u${u}`;
    assert.deepStrictEqual(
      merged.get(key),
      oracle.get(key),
      `${key}: merged {count,total_ms,max_ms} must equal oracle`
    );
  }
});
"})
